INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00012000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 12), 'unit12-lesson1', 'Need + Noun', '''Need'' is used as a main verb followed by a noun to express that something is required. The structure is Subject + need + Noun.', '{"details":[{"concept":"Basic Need","explanation":"''Need'' is used before a noun or pronoun to express a requirement.","example":"I need you.","burmese":"ငါမင်းကို လိုအပ်တယ်။"},{"concept":"Third Person Singular","explanation":"With he/she/it, ''need'' becomes ''needs''.","example":"He needs experience.","burmese":"သူ အတွေ့အကြုံ လိုတယ်။"},{"concept":"Negative Form","explanation":"Use ''don''t/doesn''t need'' + noun to express not needing something.","example":"You don''t need her.","burmese":"မင်း သူမကို မလိုဘူး။"},{"concept":"Question Form","explanation":"Use ''Do/Does + subject + need'' + noun to ask about needing something.","example":"Do you need money?","burmese":"မင်း ငွေ လိုလား။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00012001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 12), 'unit12-lesson2', 'Need to + V1', '''Need to'' is used before a verb infinitive to express that an action is necessary. The structure is Subject + need to + V1.', '{"details":[{"concept":"Necessity to Act","explanation":"''Need to'' is used before a verb to express that doing something is necessary.","example":"I need to earn money.","burmese":"ငါပိုက်ဆံရဖို့ လိုတယ်။"},{"concept":"Negative Form","explanation":"Use ''doesn''t need to'' + V1 to express that something is not necessary.","example":"She doesn''t need to go there.","burmese":"သူမ အဲဒီကို သွားဖို့ မလိုဘူး။"},{"concept":"Question Form","explanation":"Use ''Do/Does + subject + need to'' + V1 to ask about necessity.","example":"Do you need to get information?","burmese":"မင်း အချက်အလက်ရဖို့ လိုလား။"},{"concept":"Negative Question","explanation":"Use ''Don''t/Doesn''t + subject + need to'' + V1 for negative questions.","example":"Don''t they need to live in Yangon?","burmese":"သူတို့ ရန်ကုန်မှာ နေဖို့ မလိုဘူး လား။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00012000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 12), 'unit12-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1201,"question":"It is here if you ________ it.","options":["need","need to","needs"],"answer":"need","explanation":"Before a pronoun (it), use ''need'' + noun/pronoun, not ''need to''. ''Needs'' is for third person singular. Pronoun မတိုင်ခင် ''need to'' မသုံးပါ။","points":1},{"id":1202,"question":"You ________ know how toxic the product is.","options":["need to","need","needs to"],"answer":"need to","explanation":"Before a verb (know), use ''need to'' + V1. ''Need'' alone is followed by a noun, not a verb. Verb မတိုင်ခင် ''need to'' ကိုသုံးပါ။","points":1},{"id":1203,"question":"She ________ more time to recover.","options":["needs","need to","needs to"],"answer":"needs","explanation":"''She'' is third person singular, so ''need'' becomes ''needs''. Before a noun (time), use ''needs'', not ''needs to''. ''She'' က third person singular ဖြစ်တဲ့အတွက် ''needs'' ကိုသုံးပါ။","points":1},{"id":1204,"question":"I don''t ________ your comments, thank you.","options":["need","need to","needs"],"answer":"need","explanation":"Before a noun (comments), use ''need'', not ''need to''. ''Needs'' is for third person singular. Noun မတိုင်ခင် ''need to'' မသုံးပါ။","points":1},{"id":1205,"question":"Don''t go – I might ________ you.","options":["need","need to","needs"],"answer":"need","explanation":"Before a pronoun (you), use ''need'' + noun/pronoun, not ''need to''. ''Needs'' is for third person singular. Pronoun မတိုင်ခင် ''need to'' မသုံးပါ။","points":1},{"id":1206,"question":"The shirt needs ________ be washed.","options":["to","-","need"],"answer":"to","explanation":"After ''needs'' (third person singular), use ''to'' + V1 to form the infinitive. ''Needs to be washed'' is correct. ''Needs'' ပြီးနောက်မှာ ''to'' + V1 ကိုသုံးပါ။","points":1},{"id":1207,"question":"You ________ know how toxic the product is.","options":["need to","need","needs"],"answer":"need to","explanation":"Before a verb (know), use ''need to'' + V1. ''Need'' alone is followed by a noun, not a verb. Verb မတိုင်ခင် ''need to'' ကိုသုံးပါ။","points":1},{"id":1208,"question":"People ________ income not handouts.","options":["need","need to","needs"],"answer":"need","explanation":"Before a noun (income), use ''need'' + noun, not ''need to''. ''People'' is plural so ''needs'' is wrong. Noun မတိုင်ခင် ''need'' ကိုသုံးပါ။","points":1},{"id":1209,"question":"We are thirsty. We ________ a drink.","options":["need","need to","needs"],"answer":"need","explanation":"Before a noun (drink), use ''need'' + noun, not ''need to''. ''Needs'' is for third person singular. Noun မတိုင်ခင် ''need'' ကိုသုံးပါ။","points":1},{"id":1210,"question":"I want to make a cake. I ________ flour, fat and water.","options":["need","need to","needs"],"answer":"need","explanation":"Before nouns (flour, fat and water), use ''need'' + noun, not ''need to''. ''Needs'' is for third person singular. Noun များမတိုင်ခင် ''need'' ကိုသုံးပါ။","points":1},{"id":1211,"question":"Do you ________ use Facebook?","options":["need to","need","needs"],"answer":"need to","explanation":"Before a verb (use), use ''need to'' + V1. ''Need'' alone is followed by a noun, not a verb. Verb မတိုင်ခင် ''need to'' ကိုသုံးပါ။","points":1},{"id":1212,"question":"They are too tight, they ________ a big house.","options":["need","need to","needs"],"answer":"need","explanation":"Before a noun (house), use ''need'' + noun, not ''need to''. ''Needs'' is for third person singular. Noun မတိုင်ခင် ''need'' ကိုသုံးပါ။","points":1},{"id":1213,"question":"It''s too hot and Susan ________ a bath.","options":["needs","need","needs to"],"answer":"needs","explanation":"''Susan'' is third person singular, so ''need'' becomes ''needs''. Before a noun (bath), use ''needs'', not ''needs to''. ''Susan'' က third person singular ဖြစ်တဲ့အတွက် ''needs'' ကိုသုံးပါ။","points":1},{"id":1214,"question":"You don''t ________ wash the clothes.","options":["need to","need","needs"],"answer":"need to","explanation":"Before a verb (wash), use ''need to'' + V1. ''Need'' alone is followed by a noun, not a verb. Verb မတိုင်ခင် ''need to'' ကိုသုံးပါ။","points":1},{"id":1215,"question":"I ________ you.","options":["need","need to","needs"],"answer":"need","explanation":"Before a pronoun (you), use ''need'' + noun/pronoun, not ''need to''. ''Needs'' is for third person singular. Pronoun မတိုင်ခင် ''need to'' မသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

