INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00013000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 13), 'unit13-lesson1', 'Seem + Adjective', '''Seem'' is used with adjectives to describe how someone or something appears. The structure is Subject + seem + Adjective.', '{"details":[{"concept":"Describing Appearance","explanation":"''Seem'' is used with adjectives to describe how someone appears.","example":"You seem happy.","burmese":"မင်း ပျော်ပျော်ပါရတယ်။"},{"concept":"Third Person Singular","explanation":"With third person singular subjects (he, she, it), ''seem'' becomes ''seems''.","example":"He seems kind.","burmese":"သူ ကောင်းနပါရတယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00013001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 13), 'unit13-lesson2', 'Seem to + V1', '''Seem to'' is used before a verb infinitive to express how something appears to happen. The structure is Subject + seem to + V1.', '{"details":[{"concept":"Expressing Appearance of Action","explanation":"''Seem to'' is used before a verb to express how something appears to happen.","example":"You seem to know it.","burmese":"မင်း အဲဒီကို သိပါရတယ်။"},{"concept":"Negative Form","explanation":"In negatives, ''doesn''t seem to'' is used with third person singular subjects.","example":"She doesn''t seem to work there.","burmese":"သူမ အမှန် အလုပ်လုပ်ပုံ မပေါ်ဘူး။"},{"concept":"Negative Form (Plural)","explanation":"''Don''t seem to'' is used with plural subjects in negatives.","example":"They don''t seem to recognize me.","burmese":"သူတို့ ငါ့ကို မမှတ်မိပုံ မပေါ်ဘူး။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00013000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 13), 'unit13-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1301,"question":"It ________ likely that there has been a mistake.","options":["seems","seems to","seem"],"answer":"seems","explanation":"''Likely'' is an adjective, so we use ''seems'' (seems + adjective). ''Likely'' က adj ဖြစ်တဲ့အတွက် ''seems'' ကိုသုံးပါ။","points":1},{"id":1302,"question":"You ________ be nervous.","options":["seem to","seem","seems to"],"answer":"seem to","explanation":"''Be'' is a verb, so we use ''seem to'' (seem to + verb). ''Be'' က verb ဖြစ်တဲ့အတွက် ''seem to'' ကိုသုံးပါ။","points":1},{"id":1303,"question":"He ________ like classical music.","options":["seems to","seems","seem to"],"answer":"seems to","explanation":"''Like'' is a verb and ''He'' is third person singular, so we use ''seems to'' (seems to + verb). ''Like'' က verb ဖြစ်ပြီး ''He'' က third person singular ဖြစ်တဲ့အတွက် ''seems to'' ကိုသုံးပါ။","points":1},{"id":1304,"question":"She doesn''t ________ be upset.","options":["seem to","seem","seems"],"answer":"seem to","explanation":"After ''doesn''t'', we use the base form. ''Be'' is a verb, so we use ''seem to''. ''doesn''t'' ပြီးနောက်မှာ base form ''seem to'' ကိုသုံးပါ။","points":1},{"id":1305,"question":"They ________ rich.","options":["seem","seem to","seems"],"answer":"seem","explanation":"''Rich'' is an adjective and ''They'' is plural, so we use ''seem'' (seem + adjective). ''Rich'' က adj ဖြစ်ပြီး ''They'' က plural ဖြစ်တဲ့အတွက် ''seem'' ကိုသုံးပါ။","points":1},{"id":1306,"question":"Jane ________ tired.","options":["seems","seems to","seem"],"answer":"seems","explanation":"''Tired'' is an adjective and ''Jane'' is third person singular, so we use ''seems'' (seems + adjective). ''Tired'' က adj ဖြစ်ပြီး ''Jane'' က third person singular ဖြစ်တဲ့အတွက် ''seems'' ကိုသုံးပါ။","points":1},{"id":1307,"question":"Do they ________ love cat?","options":["seem to","seem","seems"],"answer":"seem to","explanation":"After ''Do'', we use the base form. ''Love'' is a verb, so we use ''seem to''. ''Do'' ပြီးနောက်မှာ base form ''seem to'' ကိုသုံးပါ။","points":1},{"id":1308,"question":"He ________ have a criminal background.","options":["seems to","seems","seem to"],"answer":"seems to","explanation":"''Have'' is a verb and ''He'' is third person singular, so we use ''seems to'' (seems to + verb). ''Have'' က verb ဖြစ်ပြီး ''He'' က third person singular ဖြစ်တဲ့အတွက် ''seems to'' ကိုသုံးပါ။","points":1},{"id":1309,"question":"She ________ excited about her job.","options":["seems","seems to","seem to"],"answer":"seems","explanation":"''Excited'' is an adjective and ''She'' is third person singular, so we use ''seems'' (seems + adjective). ''Excited'' က adj ဖြစ်ပြီး ''She'' က third person singular ဖြစ်တဲ့အတွက် ''seems'' ကိုသုံးပါ။","points":1},{"id":1310,"question":"They ________ young. How old are they?","options":["seem","seem to","seems"],"answer":"seem","explanation":"''Young'' is an adjective and ''They'' is plural, so we use ''seem'' (seem + adjective). ''Young'' က adj ဖြစ်ပြီး ''They'' က plural ဖြစ်တဲ့အတွက် ''seem'' ကိုသုံးပါ။","points":1},{"id":1311,"question":"The soup ________ be cold.","options":["seems to","seems","seem to"],"answer":"seems to","explanation":"''Be'' is a verb and ''The soup'' is third person singular, so we use ''seems to'' (seems to + verb). ''Be'' က verb ဖြစ်ပြီး ''The soup'' က third person singular ဖြစ်တဲ့အတွက် ''seems to'' ကိုသုံးပါ။","points":1},{"id":1312,"question":"He ________ be their father.","options":["seems to","seems","seem"],"answer":"seems to","explanation":"''Be'' is a verb and ''He'' is third person singular, so we use ''seems to'' (seems to + verb). ''Be'' က verb ဖြစ်ပြီး ''He'' က third person singular ဖြစ်တဲ့အတွက် ''seems to'' ကိုသုံးပါ။","points":1},{"id":1313,"question":"She ________ to cry a lot. Is she OK?","options":["seems","seems to","seem"],"answer":"seems","explanation":"The sentence already has ''to'' after the blank, so we use ''seems''. The structure is ''seems to cry''. ''to'' ကို ဘာသာစကားထဲမှာ ထည့်ပြီးသားဖြစ်တဲ့အတွက် ''seems'' ကိုသုံးပါ။","points":1},{"id":1314,"question":"Mark ________ have finished the project.","options":["seems to","seems","seem"],"answer":"seems to","explanation":"''Have finished'' is a verb phrase and ''Mark'' is third person singular, so we use ''seems to'' (seems to + verb). ''Have finished'' က verb phrase ဖြစ်ပြီး ''Mark'' က third person singular ဖြစ်တဲ့အတွက် ''seems to'' ကိုသုံးပါ။","points":1},{"id":1315,"question":"Does she ________ angry?","options":["seem","seems","seem to"],"answer":"seem","explanation":"After ''Does'', we use the base form ''seem''. ''Angry'' is an adjective, so we use ''seem'' (seem + adjective). ''Does'' ပြီးနောက်မှာ base form ''seem'' ကိုသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

