INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00014000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 14), 'unit14-lesson1', 'Want + Noun', '''Want'' is used with a noun to express desire for something. It follows the same conjugation rules as regular verbs (want/wants). The structure is Subject + Want + Noun Complement.', '{"details":[{"concept":"Want + Object Pronoun","explanation":"''Want'' can be followed by an object pronoun to express desire for a person.","example":"I want you.","burmese":"ငါမင်းကို အလိုရှိတယ်။"},{"concept":"Wants + Noun Phrase","explanation":"Third person singular uses ''wants'' followed by a noun phrase.","example":"She wants a bigger house.","burmese":"သူမ ပိုကြီးတဲ့ အိမ် လိုချင်တယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00014001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 14), 'unit14-lesson2', 'Want to + V1', '''Want to + V1'' is used to express desire to do something. After ''do/does/did'', use the base form ''want''. The structure is Subject + Want to + Verb Infinitive.', '{"details":[{"concept":"Third Person Singular","explanation":"Third person singular subjects use ''wants to'' followed by the base form of the verb.","example":"He wants to speak English.","burmese":"သူ အင်္ဂလိပ်စကားပြေးချင်တယ်။"},{"concept":"First Person Singular","explanation":"First person singular uses ''want to'' followed by the base form of the verb.","example":"I want to know about your job.","burmese":"ငါမင်းအလုပ်အကြောင်း သိချင်တယ်။"},{"concept":"Questions with Want","explanation":"In questions, ''Do/Does + subject + want to + V1'' is used.","example":"Do you want to sing a song?","burmese":"မင်း သီချင်းဆိုချင်လား။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00014002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 14), 'unit14-lesson3', 'Want (Obj) to + V1', '''Want (object) to + V1'' is used to express what you want someone else to do. The structure is Subject + Want + Object + to + V1.', '{"details":[{"concept":"Want + Me to + V1","explanation":"When you want someone else to do something, use ''want + object pronoun + to + V1''.","example":"They want me to take meditation.","burmese":"သူတို့ ငါ့ကို တရားထိုင်စေချင်တယ်။"},{"concept":"Want + Object + to + V1 (Past)","explanation":"This structure is used for desires about others in the present.","example":"My parents want me to work in Japan.","burmese":"ငါ့မိဘတွေက ငါ့ကို ဂျပန်မှာ အလုပ်လုပ်စေချင်တယ်။"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00014000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 14), 'unit14-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1401,"question":"I ________ a new car.","options":["want","want to","wants"],"answer":"want","explanation":"''Want'' is followed by a noun (''a new car''), so we use ''want''. ''Want to'' is for verbs. ''Wants'' is for third person singular. ''Want'' ပြီးနောက် noun လာရင် ''want'' ကိုသုံးပါ။","points":1},{"id":1402,"question":"She ________ read a book.","options":["wants to","wants","want to"],"answer":"wants to","explanation":"''She'' is third person singular, and the verb ''read'' follows, so we use ''wants to''. ''Wants'' without ''to'' is incorrect before a verb. ''Want to'' is for I/you/we/they. ''She'' က third person singular ဖြစ်ပြီး verb လာတဲ့အတွက် ''wants to'' ကိုသုံးပါ။","points":1},{"id":1403,"question":"Do you ________ a banana?","options":["want","want to","wants"],"answer":"want","explanation":"After ''do'', we use the base form ''want''. ''Want to'' is for verbs. ''Wants'' is for third person singular. ''Banana'' is a noun. ''Do'' ပြီးနောက်မှာ base form ''want'' ကိုသုံးပါ။","points":1},{"id":1404,"question":"I don''t ________ write a letter.","options":["want to","want","wants to"],"answer":"want to","explanation":"''Don''t want to'' is the correct negative form for ''want to + V1''. The verb ''write'' follows, so we need ''want to''. ''Want'' alone is incorrect before a verb. ''Don''t want to'' ကို verb မတိုင်ခင် သုံးပါ။","points":1},{"id":1405,"question":"He doesn''t ________ be a journalist.","options":["want","want to","wants to"],"answer":"want","explanation":"After ''doesn''t'', we use the base form ''want''. The ''to'' belongs to the infinitive ''to be''. ''Doesn''t want to'' would be redundant. ''Doesn''t'' ပြီးနောက်မှာ base form ''want'' ကိုသုံးပါ။","points":1},{"id":1406,"question":"My parents ________ be a successful man.","options":["want me to","want to","wants to"],"answer":"want me to","explanation":"''My parents'' is plural, and the sentence requires an object (''me'') before ''to be''. ''Want me to'' expresses wanting someone else to do something. ''Want to'' lacks the object. ''My parents'' က plural ဖြစ်ပြီး object (''me'') ပါဝင်တဲ့အတွက် ''want me to'' ကိုသုံးပါ။","points":1},{"id":1407,"question":"I don''t ________ go to the swimming pool.","options":["want","want to","wants"],"answer":"want","explanation":"After ''don''t'', we use the base form ''want''. The ''to'' belongs to the infinitive ''to go''. ''Don''t want to'' would be redundant. ''Wants'' is for third person singular. ''Don''t'' ပြီးနောက်မှာ base form ''want'' ကိုသုံးပါ။","points":1},{"id":1408,"question":"They ________ be an educated person.","options":["want you to","want to","wants to"],"answer":"want you to","explanation":"''They'' is plural, and the sentence requires an object (''you'') before ''to be''. ''Want you to'' expresses wanting someone else to do something. ''Want to'' lacks the object. ''They'' က plural ဖြစ်ပြီး object (''you'') ပါဝင်တဲ့အတွက် ''want you to'' ကိုသုံးပါ။","points":1},{"id":1409,"question":"Don''t you ________ her?","options":["want","want to","wants"],"answer":"want","explanation":"''Want'' is followed by an object pronoun (''her''), so we use ''want''. ''Want to'' is for verbs. ''Wants'' is for third person singular. ''Want'' ပြီးနောက် object pronoun လာရင် ''want'' ကိုသုံးပါ။","points":1},{"id":1410,"question":"We don''t ________ play hooky.","options":["want him to","want","want to"],"answer":"want him to","explanation":"''We don''t want him to'' expresses not wanting someone else to do something. The object ''him'' is required before ''to play''. ''Want'' alone lacks the object. ''We don''t want him to'' ကို တစ်စုံတစ်ယောက် မလုပ်စေချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1411,"question":"I don''t ________ be an engineer.","options":["want","want to","wants"],"answer":"want","explanation":"After ''don''t'', we use the base form ''want''. The ''to'' belongs to the infinitive ''to be''. ''Don''t want to'' would be redundant. ''Wants'' is for third person singular. ''Don''t'' ပြီးနောက်မှာ base form ''want'' ကိုသုံးပါ။","points":1},{"id":1412,"question":"You ________ me to play football.","options":["want","want to","wants"],"answer":"want","explanation":"The sentence requires an object (''me'') before ''to play''. ''Want'' is followed by the object pronoun ''me'', then ''to + V1''. ''Want to'' lacks the object. ''Wants'' is for third person singular. ''Want'' ပြီးနောက် object pronoun (''me'') ပါဝင်တဲ့အတွက် ''want'' ကိုသုံးပါ။","points":1},{"id":1413,"question":"Does Alex ________ you?","options":["want","wants","want to"],"answer":"want","explanation":"After ''does'', we use the base form ''want''. ''Wants'' is incorrect after ''does''. ''Want to'' is for verbs, but ''you'' is a pronoun (object). ''Does'' ပြီးနောက်မှာ base form ''want'' ကိုသုံးပါ။","points":1},{"id":1414,"question":"John didn''t ________ to do homework yesterday.","options":["want","wanted","wants"],"answer":"want","explanation":"After ''didn''t'', we use the base form ''want''. ''Wanted'' is incorrect after ''didn''t''. ''Wants'' is for third person singular present. ''Didn''t'' ပြီးနောက်မှာ base form ''want'' ကိုသုံးပါ။","points":1},{"id":1415,"question":"He ________ four tickets.","options":["wants","want","want to"],"answer":"wants","explanation":"''He'' is third person singular, and the verb is followed by a noun (''four tickets''), so we use ''wants''. ''Want'' is for I/you/we/they. ''Want to'' is for verbs. ''He'' က third person singular ဖြစ်ပြီး noun လာတဲ့အတွက် ''wants'' ကိုသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 15: Would like / Would like to / Would like (Obj) to
-- --------------------------------------------------------------------------

