  title = EXCLUDED.title,
  lesson_count = EXCLUDED.lesson_count,
  exercise_count = EXCLUDED.exercise_count,
  question_count = EXCLUDED.question_count;

INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00015000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 15), 'unit15-lesson1', 'Would like + Noun', 'Use ''would like + noun'' to express a desire for something. ''Would like'' is a polite way to say ''want''.', '{"details":[{"form":"would like + noun","example":"I would like a cup of tea.","burmese":"ကျွန်တော်တို့ လက်ဖက်ရည်သောက်ချင်ပါတယ်။"},{"form":"wouldn''t like + noun","example":"I wouldn''t like a cup of tea.","burmese":"ကျွန်တော်တို့ လက်ဖက်ရည် မသောက်ချင်ဘူး။"},{"form":"Would you like + noun?","example":"Would you like a sandwich?","burmese":"မင်း ဆန်းဒျ်စ်လိုချင်လား။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00015001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 15), 'unit15-lesson2', 'Would like to + V1', 'Use ''would like to + V1'' (base form) to express a desire to do something.', '{"details":[{"form":"would like to + V1","example":"I would like to drink coffee.","burmese":"ကျွန်တော်တို့ ကော်ဖီ သောက်ချင်ပါတယ်။"},{"form":"wouldn''t like to + V1","example":"They wouldn''t like to stay here.","burmese":"သူတို့ ဒီမှာ မနေချင်ကြဘူး။"},{"form":"Would you like to + V1?","example":"Would you like to see an action movie tomorrow tonight?","burmese":"မင်း မနက်ဖန်ညမှာ action movie ကြည့်ချင်လား။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00015002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 15), 'unit15-lesson3', 'Would like (Obj) to + V1', 'Use ''would like + object + to + V1'' to express a desire for someone else to do something.', '{"details":[{"form":"would like + obj + to + V1","example":"I would like you to work hard.","burmese":"ကိုယ် မင်းကို အလုပ်ကြိုးစားစေချင်တယ်။"},{"form":"wouldn''t like + obj + to + V1","example":"We wouldn''t like her to leave.","burmese":"ငါတို့ သူမကို မသွားစေချင်ဘူး။"},{"form":"Would you like + obj + to + V1?","example":"Would you like me to come with you?","burmese":"မင်း ကိုယ့်ကို မင်းနဲ့အတူလိုက်စေချင်လား။"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00015000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 15), 'unit15-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1501,"question":"I''m thirsty. I ________ a glass of water, please.","options":["would like","would like to","will like"],"answer":"would like","explanation":"After ''would like'' + noun, we use ''would like'' without ''to''. ''Would like'' + noun is used to express desire for something. ''Would like + noun'' ကို အရာဝတ္ထုတစ်ခုကို လိုချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1502,"question":"I ________ answer that question.","options":["would like to","would like","will like to"],"answer":"would like to","explanation":"After ''would like'' + verb, we use ''would like to + V1''. ''Would like to'' is used to express desire to do something. ''Would like to'' + V1 ကို လုပ်ဆောင်ချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1503,"question":"I ________ meet the president.","options":["would like to","would like","will like"],"answer":"would like to","explanation":"After ''would like'' + verb, we use ''would like to + V1''. ''Meet'' is a verb, so we need ''would like to''. ''Would like to'' + V1 ကို လုပ်ဆောင်ချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1504,"question":"Would you ________ see an action movie tomorrow tonight?","options":["like","like to","would like"],"answer":"like","explanation":"After ''Would you'', we use the base form ''like'' (not ''would like''). ''Would you like to'' is correct, but in this sentence the blank is after ''Would you'', so only ''like'' is needed. ''Would you'' ပြီးနောက်မှာ ''like'' ကိုပဲသုံးပါ။","points":1},{"id":1505,"question":"They would like me ________ flatter.","options":["to","-","would"],"answer":"to","explanation":"After ''would like + object + to'', we use ''to + V1''. The structure is: would like + object + to + V1. ''Would like + object + to + V1'' ဖွဲ့စည်းပုံမှာ ''to'' ကိုသုံးပါ။","points":1},{"id":1506,"question":"Would your kids ________ play at the park next weekend?","options":["like","like to","would like"],"answer":"like","explanation":"After ''Would'', we use the base form ''like''. The structure is: Would + subject + like + to + V1. ''Would'' ပြီးနောက်မှာ ''like'' ကိုပဲသုံးပါ။","points":1},{"id":1507,"question":"He would like me not ________ arrive late.","options":["to","-","would"],"answer":"to","explanation":"After ''would like + object + not to'', we use ''to + V1''. The structure is: would like + object + not to + V1. ''Would like + object + not to + V1'' ဖွဲ့စည်းပုံမှာ ''to'' ကိုသုံးပါ။","points":1},{"id":1508,"question":"She ________ some coffee.","options":["would like","would like to","will like"],"answer":"would like","explanation":"After ''would like'' + noun, we use ''would like'' without ''to''. ''Some coffee'' is a noun phrase. ''Would like + noun'' ကို အရာဝတ္ထုတစ်ခုကို လိုချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1509,"question":"________ come with us.","options":["would like you to","would you like to","would like to"],"answer":"would like you to","explanation":"The structure is: subject + would like + object + to + V1. ''You'' is the object, so we use ''would like you to''. ''Would like + object + to + V1'' ဖွဲ့စည်းပုံမှာ object ကိုထည့်ပါ။","points":1},{"id":1510,"question":"________ have dessert.","options":["would like her to","would her like to","would like to"],"answer":"would like her to","explanation":"The structure is: subject + would like + object + to + V1. ''Her'' is the object, so we use ''would like her to''. ''Would like + object + to + V1'' ဖွဲ့စည်းပုံမှာ object ကိုထည့်ပါ။","points":1},{"id":1511,"question":"They ________ speak English well.","options":["would like to","would like","will like"],"answer":"would like to","explanation":"After ''would like'' + verb, we use ''would like to + V1''. ''Speak'' is a verb, so we need ''would like to''. ''Would like to'' + V1 ကို လုပ်ဆောင်ချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1512,"question":"I ________ go abroad.","options":["would like to","would like","will like"],"answer":"would like to","explanation":"After ''would like'' + verb, we use ''would like to + V1''. ''Go'' is a verb, so we need ''would like to''. ''Would like to'' + V1 ကို လုပ်ဆောင်ချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1513,"question":"Who ________ some candy?","options":["would like","would like to","will like"],"answer":"would like","explanation":"After ''would like'' + noun, we use ''would like'' without ''to''. ''Some candy'' is a noun phrase. ''Would like + noun'' ကို အရာဝတ္ထုတစ်ခုကို လိုချင်တဲ့အခါ သုံးပါ။","points":1},{"id":1514,"question":"John would like his baby ________ take a nap in daytime.","options":["to","-","would"],"answer":"to","explanation":"After ''would like + object + to'', we use ''to + V1''. The structure is: would like + object + to + V1. ''Would like + object + to + V1'' ဖွဲ့စည်းပုံမှာ ''to'' ကိုသုံးပါ။","points":1},{"id":1515,"question":"I ________ play tennis today.","options":["would like to","would like","will like"],"answer":"would like to","explanation":"After ''would like'' + verb, we use ''would like to + V1''. ''Play'' is a verb, so we need ''would like to''. ''Would like to'' + V1 ကို လုပ်ဆောင်ချင်တဲ့အခါ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 16: Going to
-- --------------------------------------------------------------------------

INSERT INTO units (id, unit_number, title, lesson_count, exercise_count, question_count)
VALUES ('00000016-0000-4000-8000-000000000001', 16, 'Going to', 2, 1, 15)
ON CONFLICT (unit_number) DO UPDATE SET
  id = EXCLUDED.id,
  title = EXCLUDED.title,
  lesson_count = EXCLUDED.lesson_count,
  exercise_count = EXCLUDED.exercise_count,
  question_count = EXCLUDED.question_count;

INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00016000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 16), 'unit16-lesson1', 'Going to for Future Plans', '''Going to'' is used to talk about plans and intentions for the future. The structure is Subject + am/is/are + going to + V1.', '{"details":[{"concept":"Personal Future Plan","explanation":"''Going to'' is used when we have already decided to do something in the future.","example":"I am going to play football with my friends.","burmese":"ငါ သူငယ်ချင်းတွေနဲ့ ဘောလုံး ကစားတော့မယ်။"},{"concept":"Someone Else''s Plan","explanation":"''Going to'' is used to talk about another person''s future plans.","example":"The baby is going to sleep.","burmese":"ကလေး အိပ်တော့မယ်။"},{"concept":"Scheduled Future Action","explanation":"''Going to'' is used for actions that are already scheduled or arranged.","example":"She is going to visit her grandmother next week.","burmese":"သူမ နောက်အပတ်မှာ အဘိုးအဘွားဆီ သွားလည်မယ်။"},{"concept":"Group Plan","explanation":"''Going to'' is used when a group has a plan together.","example":"We are going to have a meeting tomorrow.","burmese":"ငါတို့ မနက်ဖြန် အစည်းအဝေး လုပ်မယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00016001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 16), 'unit16-lesson2', 'Going to for Predictions', '''Going to'' is used to make predictions based on what we can see now — present evidence. The structure is Subject + am/is/are + going to + V1.', '{"details":[{"concept":"Prediction Based on Feeling","explanation":"''Going to'' is used when we predict something based on how we feel now.","example":"I think I am going to be sick.","burmese":"ငါ အန်မယ်ဖြစ်တော့မယ်လို့ ထင်တယ်။"},{"concept":"Prediction in Question Form","explanation":"''Going to'' can be used in questions to ask about future predictions.","example":"Are you going to take a bath?","burmese":"မင်း ရေချိုးတော့မလား လဲ။"},{"concept":"Prediction Based on Visual Evidence","explanation":"''Going to'' is used when we can see something that tells us what will happen.","example":"Look at those dark clouds. It is going to rain.","burmese":"မိုးညိုတိမ်တွေ ကြည့်ပါ။ မိုးရွာတော့မယ်။"},{"concept":"Prediction Based on Body Language","explanation":"''Going to'' is used when we can see someone''s expression or behavior.","example":"She is going to cry. Look at her face.","burmese":"သူမ ငိုတော့မယ်။ မျက်နှာကြည့်ပါ။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00016000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 16), 'unit16-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1601,"question":"I ________ visit my parents tomorrow.","options":["am going to","will going to","am going"],"answer":"am going to","explanation":"''Going to'' is used for future plans. The structure is ''am/is/are + going to + V1''. ''Will going to'' is grammatically incorrect. ''Am going'' needs ''to'' before the verb. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1602,"question":"Look! The baby ________ cry.","options":["is going to","are going to","goes to"],"answer":"is going to","explanation":"''Going to'' is used for predictions based on present evidence. We can see the baby is about to cry. ''Goes to'' is for habitual actions. ''Going to'' ကို လက်ရှိအခြေအနေအပေါ် အခြေခံတဲ့ ခန့်မှန်းချက်တွေမှာ သုံးပါ။","points":1},{"id":1603,"question":"She ________ cook dinner tonight.","options":["is going to","are going to","goes to"],"answer":"is going to","explanation":"''Going to'' is used for future plans. ''She'' takes ''is''. The structure is ''is + going to + V1''. ''Are going to'' is for plural subjects. ''Goes to'' is for habitual actions. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1604,"question":"They ________ not come to the party.","options":["are going to","is going to","were going"],"answer":"are going to","explanation":"''Going to'' is used for future plans. ''They'' takes ''are''. The negative form is ''are not going to + V1''. ''Is going to'' is for singular subjects. ''Were going'' is past tense. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1605,"question":"What ________ you do this weekend?","options":["are you going to","do you going to","are you going"],"answer":"are you going to","explanation":"''Going to'' is used in questions about future plans. The question form is ''What + am/is/are + subject + going to + V1?''. ''Do you going to'' is grammatically incorrect. ''Are you going'' needs ''to'' before the verb. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1606,"question":"I think it ________ rain later.","options":["is going to","are going to","will going to"],"answer":"is going to","explanation":"''Going to'' is used for predictions based on present evidence. ''It'' takes ''is''. The structure is ''is + going to + V1''. ''Are going to'' is for plural subjects. ''Will going to'' is grammatically incorrect. ''Going to'' ကို လက်ရှိအခြေအနေအပေါ် အခြေခံတဲ့ ခန့်မှန်းချက်တွေမှာ သုံးပါ။","points":1},{"id":1607,"question":"We ________ move to a new house next month.","options":["are going to","is going to","goes to"],"answer":"are going to","explanation":"''Going to'' is used for future plans. ''We'' takes ''are''. The structure is ''are + going to + V1''. ''Is going to'' is for singular subjects. ''Goes to'' is for habitual actions. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1608,"question":"He ________ buy a new car.","options":["is going to","are going to","goes to"],"answer":"is going to","explanation":"''Going to'' is used for future plans. ''He'' takes ''is''. The structure is ''is + going to + V1''. ''Are going to'' is for plural subjects. ''Goes to'' is for habitual actions. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1609,"question":"________ you going to help me?","options":["Are","Do","Is"],"answer":"Are","explanation":"''Going to'' questions use am/is/are. ''You'' takes ''Are''. The question form is ''Are + subject + going to + V1?''. ''Do'' is used with other verb forms. ''Is'' is for singular third person. ''Going to'' ကို မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1610,"question":"I ________ study hard for the exam.","options":["am going to","is going to","goes to"],"answer":"am going to","explanation":"''Going to'' is used for future plans. ''I'' takes ''am''. The structure is ''am + going to + V1''. ''Is going to'' is for singular third person. ''Goes to'' is for habitual actions. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1611,"question":"She ________ not going to attend the meeting.","options":["is","are","am"],"answer":"is","explanation":"The negative form is ''is not going to + V1''. ''She'' takes ''is''. ''Are'' is for plural subjects or ''you''. ''Am'' is only for ''I''. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1612,"question":"The weather is bad. We ________ stay home.","options":["are going to","is going to","goes to"],"answer":"are going to","explanation":"''Going to'' is used for predictions based on present evidence. ''We'' takes ''are''. The structure is ''are + going to + V1''. ''Is going to'' is for singular subjects. ''Goes to'' is for habitual actions. ''Going to'' ကို လက်ရှိအခြေအနေအပေါ် အခြေခံတဲ့ ခန့်မှန်းချက်တွေမှာ သုံးပါ။","points":1},{"id":1613,"question":"Look at those dark clouds. It ________ storm.","options":["is going to","are going to","goes to"],"answer":"is going to","explanation":"''Going to'' is used for predictions based on present evidence — we can see dark clouds. ''It'' takes ''is''. ''Are going to'' is for plural subjects. ''Goes to'' is for habitual actions. ''Going to'' ကို လက်ရှိအခြေအနေအပေါ် အခြေခံတဲ့ ခန့်မှန်းချက်တွေမှာ သုံးပါ။","points":1},{"id":1614,"question":"My parents ________ visit us next weekend.","options":["are going to","is going to","goes to"],"answer":"are going to","explanation":"''Going to'' is used for future plans. ''My parents'' is plural, so it takes ''are''. The structure is ''are + going to + V1''. ''Is going to'' is for singular subjects. ''Goes to'' is for habitual actions. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1},{"id":1615,"question":"What ________ she eat for lunch?","options":["is she going to","does she going to","is she going"],"answer":"is she going to","explanation":"''Going to'' is used in questions about future plans. The question form is ''What + is + subject + going to + V1?''. ''Does she going to'' is grammatically incorrect. ''Is she going'' needs ''to'' before the verb. ''Going to'' ကို အနာဂတ်အစီအစဉ်တွေမှာ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

